function w({registerIndicator:b,nulls:N}){b({id:"oa-bop",name:"Balance of Power (BOP)",category:"Momentum",placement:"pane",inputs:[{key:"smoothing",type:"number",label:"Smoothing Length",default:14,min:0,max:5e3,step:1,tooltip:"0 for no smoothing."}],plots:[{key:"bop",type:"line",title:"BOP",style:{color:"#ffeb3b",lineWidth:2}}],calc(r,g){const m=r.length,i=g.smoothing,u=i===""||i===null||i===void 0?14:Number(i),p=Number.isFinite(u)?Math.max(0,Math.floor(u)):14,n=new Array(m).fill(NaN),f=2/(p+1);let e=NaN,l=1,h=!1;for(let o=0;o<m;o++){const t=r[o],a=t.high,c=t.low;if(!Number.isFinite(a)||!Number.isFinite(c)||!Number.isFinite(t.close)||!Number.isFinite(t.open))continue;const s=a===c?0:(t.close-t.open)/(a-c);if(p===0){n[o]=s;continue}if(!Number.isFinite(e)){e=s,n[o]=s;continue}if(e=f*(s-e)+e,h)n[o]=e;else{l*=1-f;const d=l>1e-10?1/(1-l):1;n[o]=e*d,l<=1e-10&&(h=!0)}}return{bop:N(n)}}})}export{w as default};
